AssistantMessageToolRequest(name='create', tool_call_id='toolu_01GYyH1fDH7zJiTygxGz8BBh', arguments={'file_text': ':root {
  --bg-0: #0b0d12;
  --bg-1: #12151c;
  --bg-2: #1a1f29;
  --bg-3: #232938;
  --border: #2a3142;
  --border-strong: #384057;
  --text: #e7eaf2;
  --text-dim: #9aa3b6;
  --text-faint: #6b7488;
  --danger: #ef4444;
  --danger-hover: #dc2626;
  --danger-glow: rgba(239, 68, 68, 0.35);
  --accent: #6366f1;
  --shadow-lg: 0 25px 60px -15px rgba(0, 0, 0, 0.7), 0 0 0 1px rgba(255,255,255,0.04);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  background: radial-gradient(1200px 800px at 70% -10%, #1a2030 0%, var(--bg-0) 60%);
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Inter, Roboto, sans-serif;
  min-height: 100vh;
  -webkit-font-smoothing: antialiased;
}

.page {
  max-width: 880px;
  margin: 0 auto;
  padding: 48px 24px 80px;
}

.page-header h1 {
  margin: 0;
  font-size: 28px;
  letter-spacing: -0.02em;
}
.subtitle {
  margin: 6px 0 32px;
  color: var(--text-dim);
  font-size: 14px;
}

.preview {
  margin: 0;
  background: var(--bg-1);
  border: 1px solid var(--border);
  border-radius: 16px;
  overflow: hidden;
  box-shadow: 0 10px 40px -20px rgba(0,0,0,0.6);
}

.preview-frame {
  background: #000;
  aspect-ratio: 16 / 10;
  overflow: hidden;
}
.preview-frame img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.preview-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 18px 22px;
  border-top: 1px solid var(--border);
  flex-wrap: wrap;
}
.preview-meta h2 {
  margin: 0 0 4px;
  font-size: 16px;
  font-weight: 600;
}
.preview-meta p {
  margin: 0;
  font-size: 13px;
  color: var(--text-faint);
}

.actions {
  display: flex;
  gap: 8px;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font: inherit;
  font-size: 14px;
  font-weight: 500;
  padding: 9px 16px;
  border-radius: 8px;
  border: 1px solid transparent;
  cursor: pointer;
  transition: background 120ms ease, border-color 120ms ease, transform 80ms ease, box-shadow 120ms ease;
  color: var(--text);
}
.btn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}
.btn:active { transform: translateY(1px); }

.btn-ghost {
  background: var(--bg-2);
  border-color: var(--border);
  color: var(--text);
}
.btn-ghost:hover {
  background: var(--bg-3);
  border-color: var(--border-strong);
}

.btn-danger {
  background: var(--danger);
  color: #fff;
  border-color: transparent;
}
.btn-danger:hover {
  background: var(--danger-hover);
  box-shadow: 0 6px 18px -4px var(--danger-glow);
}

/* Modal */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(5, 7, 12, 0.7);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  z-index: 100;
  animation: fade-in 160ms ease-out;
}
.modal-backdrop[hidden] { display: none; }

.modal {
  position: relative;
  width: 100%;
  max-width: 420px;
  background: linear-gradient(180deg, #1b212e 0%, #161b25 100%);
  border: 1px solid var(--border-strong);
  border-radius: 14px;
  padding: 28px 26px 22px;
  box-shadow: var(--shadow-lg);
  animation: pop-in 180ms cubic-bezier(0.2, 0.9, 0.3, 1.1);
}

.modal-icon {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(239, 68, 68, 0.12);
  color: var(--danger);
  border: 1px solid rgba(239, 68, 68, 0.25);
  margin-bottom: 16px;
}

.modal-title {
  margin: 0 0 8px;
  font-size: 18px;
  font-weight: 600;
  letter-spacing: -0.01em;
}
.modal-desc {
  margin: 0 0 22px;
  color: var(--text-dim);
  font-size: 14px;
  line-height: 1.5;
}

.modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}

.modal-close {
  position: absolute;
  top: 12px;
  right: 12px;
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: none;
  border-radius: 6px;
  color: var(--text-faint);
  cursor: pointer;
  transition: background 120ms ease, color 120ms ease;
}
.modal-close:hover {
  background: var(--bg-3);
  color: var(--text);
}
.modal-close:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

@keyframes fade-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}
@keyframes pop-in {
  from { opacity: 0; transform: translateY(8px) scale(0.96); }
  to   { opacity: 1; transform: translateY(0)   scale(1); }
}

@media (max-width: 520px) {
  .preview-meta { padding: 16px; }
  .modal { padding: 24px 20px 18px; }
}
